// Code_Prepare_Top10_ForExtraction
// Extrait searchResultSelected depuis le contexte et itère sur chaque résultat Top-10
// Prépare les données pour l'analyse LLM

const inputItem = $input.first().json;
const searchResultSelected = inputItem.context?.searchResultSelected || [];

if (!Array.isArray(searchResultSelected) || searchResultSelected.length === 0) {
  return [];
}

// Récupérer les données du contexte (optimisé)
const strategicQuestion = $('Condition_Check_IsSuccess1').first().json.context?.strategicQuestion || null;
const initData = $('Code_Initialize_WatchFileData').first().json;
const watchFile = initData.watchFile || null;
const language = initData.language || 'en';

// Préparer chaque résultat Top-10 pour l'analyse LLM
return searchResultSelected
  .filter(result => result.id) // Filtrer les résultats sans ID
  .map(result => ({
    json: {
      searchResult: {
        id: result.id,
        title: result.title || '',
        description: result.description || result.snippet || '',
        url: result.url || '',
        content: result.content || result.description || result.snippet || '',
        domain: result.domain || null,
        publishDate: result.publishDate || null,
        googleRanking: result.googleRanking || null,
        qualityScore: result.qualityScore || null,
        selectionRank: result.selectionRank || null
      },
      strategicQuestion: strategicQuestion, // Envoyer tout l'objet strategicQuestion
      watchFile: watchFile, // Envoyer tout l'objet watchFile
      language: language
    }
  }));

