const inputItems = $input.all().map(item => item.json);

return inputItems.map(input => {
  const output = input.output || input;
  const searchResultId = output.searchResultId || 
    $('Code_SearchResult_PrepareTop10ForExtraction').first()?.json?.searchResult?.id;

  const formattedExtractions = [];
  const { actors = [], sources = [], topics = [] } = output.extractions || {};

  // ✅ ACTORS - Conserver TOUTE la structure originale
  actors.forEach(actor => {
    if (actor.confidence >= 0.6) {
      const actorData = {};

      // Copier TOUS les champs de l'actor original
      if (actor.label !== undefined) actorData.label = actor.label;
      if (actor.type !== undefined) actorData.type = actor.type;
      if (actor.primaryDomain !== undefined) actorData.primaryDomain = actor.primaryDomain;
      if (actor.score !== undefined) actorData.score = actor.score;
      if (actor.explanation_fr !== undefined) actorData.explanation_fr = actor.explanation_fr;
      if (actor.explanation_en !== undefined) actorData.explanation_en = actor.explanation_en;
      if (actor.description !== undefined) actorData.description = actor.description;

      formattedExtractions.push({
        type: 'actor',
        data: actorData,
        confidenceScore: actor.confidence || 0.0
      });
    }
  });

  // ✅ SOURCES - Conserver TOUTE la structure originale
  sources.forEach(source => {
    if (source.confidence >= 0.6) {
      const sourceData = {};

      // Copier TOUS les champs de la source originale
      if (source.name !== undefined) sourceData.name = source.name;
      if (source.url !== undefined) sourceData.url = source.url;
      if (source.type !== undefined) sourceData.type = source.type;
      if (source.primaryDomain !== undefined) sourceData.primaryDomain = source.primaryDomain;
      if (source.description_fr !== undefined) sourceData.description_fr = source.description_fr;
      if (source.description_en !== undefined) sourceData.description_en = source.description_en;
      if (source.description !== undefined) sourceData.description = source.description;
      if (source.relevance_fr !== undefined) sourceData.relevance_fr = source.relevance_fr;
      if (source.relevance_en !== undefined) sourceData.relevance_en = source.relevance_en;
      if (source.score !== undefined) sourceData.score = source.score;
      if (source.query !== undefined) sourceData.query = source.query;

      formattedExtractions.push({
        type: 'source',
        data: sourceData,
        confidenceScore: source.confidence || 0.0
      });
    }
  });

  // ✅ TOPICS - Conserver TOUTE la structure originale
  topics.forEach(topic => {
    if (topic.confidence >= 0.6) {
      const topicData = {};

      // Copier TOUS les champs du topic original
      if (topic.name !== undefined) topicData.name = topic.name;
      if (topic.type !== undefined) topicData.type = topic.type;
      if (topic.primaryDomain !== undefined) topicData.primaryDomain = topic.primaryDomain;
      if (topic.explanation !== undefined) topicData.explanation = topic.explanation;
      if (topic.description !== undefined) topicData.description = topic.description;
      if (topic.score !== undefined) topicData.score = topic.score;

      formattedExtractions.push({
        type: 'topic',
        data: topicData,
        confidenceScore: topic.confidence || 0.0
      });
    }
  });

  return {
    json: {
      searchResultId,
      extractions: formattedExtractions
    }
  };
});

