const inputItems = $input.all();
const queryCount = inputItems.length;
const language = $('Code_Initialize_WatchFileData').first().json.language || 'en';

const message = language === 'fr'
  ? `🌐 Recherche web en cours (${queryCount} requête${queryCount > 1 ? 's' : ''})...`
  : `🌐 Web search in progress (${queryCount} quer${queryCount !== 1 ? 'ies' : 'y'})...`;

return {
  json: {
    message
  }
};

// Code_Build_EnrichmentProgressMessage
const language = $('Code_Initialize_WatchFileData').first().json.language || 'en';

const message = language === 'fr'
  ? `✅ Enrichissement WatchFile en cours...`
  : `✅ WatchFile enrichment in progress...`;

return {
  json: {
    message
  }
}

const initData = $('Code_Initialize_WatchFileData').first().json;
const language = initData.language || 'en';
const watchFileName = initData.watchFile?.name || 'WatchFile';
const builderResults = $input.all();

let actorsAdded = 0;
let sourcesAdded = 0;
let topicsIdentified = 0;
let duplicatesAvoided = 0;

builderResults.forEach(item => {
  const json = item.json || {};

  // Compter les acteurs
  if (json.actor) {
    if (json.actor.success === true) {
      actorsAdded++;
    } else if (json.actor.message && (
      json.actor.message.toLowerCase().includes('duplicate') || 
      json.actor.message.toLowerCase().includes('déjà') ||
      json.actor.message.toLowerCase().includes('already')
    )) {
      duplicatesAvoided++;
    }
  }

  // Compter les sources
  if (json.source) {
    if (json.source.success === true) {
      sourcesAdded++;
    } else if (json.source.message && (
      json.source.message.toLowerCase().includes('duplicate') || 
      json.source.message.toLowerCase().includes('déjà') ||
      json.source.message.toLowerCase().includes('already')
    )) {
      duplicatesAvoided++;
    }
  }

  // Compter les sujets
  if (json.referenceSubject?.success === true) {
    topicsIdentified++;
  }
});

const message = language === 'fr'
  ? `✅ **Recherche approfondie terminée !**\n\nVotre dossier de veille **${watchFileName}** a été enrichi :\n- **${actorsAdded} acteur${actorsAdded > 1 ? 's' : ''}** ajouté${actorsAdded > 1 ? 's' : ''}${duplicatesAvoided > 0 ? ` (${duplicatesAvoided} doublon${duplicatesAvoided > 1 ? 's' : ''} évité${duplicatesAvoided > 1 ? 's' : ''})` : ''}\n- **${sourcesAdded} source${sourcesAdded > 1 ? 's' : ''}** configurée${sourcesAdded > 1 ? 's' : ''} automatiquement\n- **${topicsIdentified} sujet${topicsIdentified > 1 ? 's' : ''}** identifié${topicsIdentified > 1 ? 's' : ''}, mise à jour du sujet de référence\n\n💬 Souhaitez-vous ajuster la configuration ou ajouter d'autres éléments ?`
  : `✅ **Deep search completed!**\n\nYour watch file **${watchFileName}** has been enriched:\n- **${actorsAdded} actor${actorsAdded !== 1 ? 's' : ''}** added${duplicatesAvoided > 0 ? ` (${duplicatesAvoided} duplicate${duplicatesAvoided !== 1 ? 's' : ''} avoided)` : ''}\n- **${sourcesAdded} source${sourcesAdded !== 1 ? 's' : ''}** automatically configured\n- **${topicsIdentified} topic${topicsIdentified !== 1 ? 's' : ''}** identified, reference subject updated\n\n💬 Would you like to adjust the configuration or add other elements?`;

return {
  json: {
    message,
    stats: {
      actorsAdded,
      sourcesAdded,
      topicsIdentified,
      duplicatesAvoided,
      totalItems: builderResults.length
    }
  }
};
